import json

# Load new results
with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_4/projects/distrib_canary_collapse/artifacts/conditional_granger_v2.json') as f:
    new = json.load(f)

results = new['results']
downstreams = ['distinct_1', 'distinct_2', 'distinct_3', 'mauve']

for alpha_label, alpha in [("α=0.05", 0.05), ("α=0.10", 0.10)]:
    counts = {'entropy_only': 0, 'ece_only': 0, 'both_independent': 0, 'redundant': 0, 'neither': 0}
    total_pairs = 0

    for exp_name, exp_data in results.items():
        for ds in downstreams:
            if ds not in exp_data['pairs']:
                continue
            pair = exp_data['pairs'][ds]
            total_pairs += 1

            # lag=1 conditional p-values
            p_ent = pair['cond_entropy_given_ece']['1']['p_value']
            p_ece = pair['cond_ece_given_entropy']['1']['p_value']

            ent_sig = p_ent < alpha
            ece_sig = p_ece < alpha

            if ent_sig and ece_sig:
                counts['both_independent'] += 1
            elif ent_sig and not ece_sig:
                counts['entropy_only'] += 1
            elif not ent_sig and ece_sig:
                counts['ece_only'] += 1
            else:
                # Neither conditional is significant — check unconditional
                p_ent_uncond = pair['uncond_entropy']['1']['p_value']
                p_ece_uncond = pair['uncond_ece']['1']['p_value']
                if p_ent_uncond < alpha or p_ece_uncond < alpha:
                    counts['redundant'] += 1
                else:
                    counts['neither'] += 1

    print(f"\n=== {alpha_label} (N={len(results)} experiments, {total_pairs} pairs) ===")
    for k, v in counts.items():
        pct = v / total_pairs * 100
        print(f"  {k:20s}: {v:3d} ({pct:5.1f}%)")

# Partial R² summary
print("\n=== Partial R² (lag=1) ===")
ent_pr2_list = []
ece_pr2_list = []
for exp_name, exp_data in results.items():
    for ds in downstreams:
        if ds not in exp_data['pairs']:
            continue
        pair = exp_data['pairs'][ds]
        # Compute partial R² from F-stats and df
        for test_key, pr2_list in [('cond_entropy_given_ece', ent_pr2_list), ('cond_ece_given_entropy', ece_pr2_list)]:
            f = pair[test_key]['1']['F_stat']
            df = pair[test_key]['1']['df']
            df1, df2 = df[0], df[1]
            pr2 = (df1 * f) / (df1 * f + df2)
            pr2_list.append(pr2)

import statistics
print(f"  Entropy|ECE: mean={statistics.mean(ent_pr2_list):.4f}, median={statistics.median(ent_pr2_list):.4f}")
print(f"  ECE|Entropy: mean={statistics.mean(ece_pr2_list):.4f}, median={statistics.median(ece_pr2_list):.4f}")
print(f"  Entropy > ECE in {sum(1 for e, c in zip(ent_pr2_list, ece_pr2_list) if e > c)}/{len(ent_pr2_list)} pairs")

# Breakdown by experiment category
print("\n=== Dominance by category (α=0.05) ===")
categories = {
    'alpha_sweep': [k for k in results if k.startswith('a') and not k.startswith('a0') or k.startswith('a0')],
    'C4': [k for k in results if k.startswith('c4_')],
    'generalize': [k for k in results if k.startswith(('pythia', 'qwen', 'smollm'))],
    'T=20': [k for k in results if k.startswith('t20_')],
}
# Fix alpha_sweep to exclude others
categories['alpha_sweep'] = [k for k in results if not k.startswith(('c4_', 'pythia', 'qwen', 'smollm', 't20_'))]

for cat_name, cat_keys in categories.items():
    cat_counts = {'entropy_only': 0, 'ece_only': 0, 'both': 0, 'redundant': 0, 'neither': 0}
    n_pairs = 0
    for exp_name in cat_keys:
        exp_data = results[exp_name]
        for ds in downstreams:
            if ds not in exp_data['pairs']:
                continue
            pair = exp_data['pairs'][ds]
            n_pairs += 1
            p_ent = pair['cond_entropy_given_ece']['1']['p_value']
            p_ece = pair['cond_ece_given_entropy']['1']['p_value']
            if p_ent < 0.05 and p_ece < 0.05:
                cat_counts['both'] += 1
            elif p_ent < 0.05:
                cat_counts['entropy_only'] += 1
            elif p_ece < 0.05:
                cat_counts['ece_only'] += 1
            else:
                p_eu = pair['uncond_entropy']['1']['p_value']
                p_cu = pair['uncond_ece']['1']['p_value']
                if p_eu < 0.05 or p_cu < 0.05:
                    cat_counts['redundant'] += 1
                else:
                    cat_counts['neither'] += 1
    print(f"\n  {cat_name} ({len(cat_keys)} exps, {n_pairs} pairs):")
    for k, v in cat_counts.items():
        print(f"    {k:15s}: {v:2d} ({v/n_pairs*100:.0f}%)")
